import{_ as l,r as i,o as c,c as d,e as n,a as t,s,d as a}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Sending Campaigns - October CMS User Guide","titleTemplate":false,"description":"Compose and send your first email campaign to subscribers.","frontmatter":{"subtitle":"Compose and send your first email campaign to subscribers."},"headers":[{"level":2,"title":"Creating a Campaign","slug":"creating-a-campaign","link":"#creating-a-campaign","children":[]},{"level":2,"title":"Editing Campaign Content","slug":"editing-campaign-content","link":"#editing-campaign-content","children":[]},{"level":2,"title":"Personalization Tags","slug":"personalization-tags","link":"#personalization-tags","children":[]},{"level":2,"title":"Previewing and Testing","slug":"previewing-and-testing","link":"#previewing-and-testing","children":[]},{"level":2,"title":"Launching the Campaign","slug":"launching-the-campaign","link":"#launching-the-campaign","children":[]},{"level":2,"title":"Campaign Statuses","slug":"campaign-statuses","link":"#campaign-statuses","children":[]},{"level":2,"title":"Scheduling and Automation","slug":"scheduling-and-automation","link":"#scheduling-and-automation","children":[]},{"level":2,"title":"Try It Out","slug":"try-it-out","link":"#try-it-out","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/mailing-list/sending-campaigns.md","filePath":"user-guide/mailing-list/sending-campaigns.md"}'),g={name:"user-guide/mailing-list/sending-campaigns.md"};function h(u,e,p,m,b,f){const r=i("pre-heading"),o=i("post-heading");return c(),d("div",null,[n(r),e[0]||(e[0]=t("h1",null,"Sending Campaigns",-1)),n(o),e[1]||(e[1]=s(`<p>With subscribers on your list, you are ready to send them content. In this step, you will compose a campaign using the default template, preview it, and launch it to your subscriber list.</p><h2 id="creating-a-campaign"><a href="#creating-a-campaign" class="header-anchor">#</a> Creating a Campaign</h2><p>Navigate to <strong>Mailing List &gt; Campaigns</strong> and click <strong>New Campaign</strong>. Enter a name for your campaign (e.g., &quot;Welcome Newsletter&quot;) and select the &quot;Default template&quot; page that was generated earlier. Click <strong>Create Campaign</strong> to save it.</p><p>The campaign is created in <strong>Draft</strong> status. While in draft, you can edit the content as many times as you like.</p><h2 id="editing-campaign-content"><a href="#editing-campaign-content" class="header-anchor">#</a> Editing Campaign Content</h2><p>After creating the campaign, the template&#39;s syntax fields appear as an editable form. The default template includes several fields:</p><ul><li><strong>Introductory message</strong>: the headline text. The default is &quot;Hello there, {first_name}!&quot; which will be personalized with each subscriber&#39;s first name.</li><li><strong>Banner image</strong>: upload an image to display at the top of the email.</li><li><strong>Opening statement</strong>: a short paragraph introducing the email.</li><li><strong>Content sections</strong>: a repeating field where you can add multiple sections, each with a heading and rich text content. Click &quot;Add another content section&quot; to add more.</li><li><strong>Salutation</strong>: a closing message.</li></ul><p>Fill in these fields with your content. The right sidebar shows a content guide with available template tags and formatting tips.</p><h2 id="personalization-tags"><a href="#personalization-tags" class="header-anchor">#</a> Personalization Tags</h2><p>Campaign emails support personalization tags that are replaced with subscriber-specific values when the email is sent:</p><div class="table"><table tabindex="0"><thead><tr><th>Tag</th><th>Description</th></tr></thead><tbody><tr><td><code>{first_name}</code></td><td>Subscriber&#39;s first name</td></tr><tr><td><code>{last_name}</code></td><td>Subscriber&#39;s last name</td></tr><tr><td><code>{email}</code></td><td>Subscriber&#39;s email address</td></tr><tr><td><code>{unsubscribe_url}</code></td><td>Link for the subscriber to opt out</td></tr><tr><td><code>{browser_url}</code></td><td>Link to view the email in a web browser</td></tr></tbody></table></div><p>You can use these tags both in the syntax field content and directly in the template HTML. The <code>{first_name}</code> tag is already used in the default template&#39;s greeting.</p><h2 id="previewing-and-testing"><a href="#previewing-and-testing" class="header-anchor">#</a> Previewing and Testing</h2><p>Before launching, you can preview the campaign and send a test email. Click the <strong>Send Test Message</strong> button, enter your own email address, and click <strong>Send</strong>. You can optionally select a subscriber list and a specific subscriber to see how the personalization tags resolve for that person.</p><p>Check your inbox for the test email. Verify that the content looks correct, the personalization tags resolved properly, and the &quot;View in browser&quot; and &quot;Unsubscribe&quot; links work.</p><h2 id="launching-the-campaign"><a href="#launching-the-campaign" class="header-anchor">#</a> Launching the Campaign</h2><p>When you are satisfied with the content, click <strong>Launch Campaign</strong>. You will be asked to select which subscribers should receive the email.</p><p>Under <strong>Subscriber Lists</strong>, select the &quot;Newsletter&quot; list. If you have RainLab.User installed, you will also see <strong>Recipient Groups</strong> like &quot;All registered users&quot; that you can select alongside your lists.</p><p>The launch dialog offers several options:</p><ul><li><strong>Delayed launch</strong>: check this to schedule the campaign for a specific date and time. The campaign will stay in Pending status until the scheduled time.</li><li><strong>Staggered launch</strong>: divides subscribers into smaller groups and sends in batches. Useful for large lists to avoid email provider rate limits. You can stagger by time period or by a fixed number of messages per batch.</li><li><strong>Repeat frequency</strong>: automatically duplicates the campaign after it is sent and schedules the next send. This is covered in the <a href="./dynamic-campaigns.html">Dynamic Campaigns</a> chapter.</li></ul><p>For your first campaign, leave these options unchecked and click <strong>Launch</strong>. The campaign will process immediately.</p><h2 id="campaign-statuses"><a href="#campaign-statuses" class="header-anchor">#</a> Campaign Statuses</h2><p>A campaign moves through several statuses during its lifecycle:</p><ul><li><strong>Draft</strong>: content is being edited. This is the only status where you can modify the campaign.</li><li><strong>Pending</strong>: the campaign is scheduled but has not reached its launch date yet.</li><li><strong>Processing</strong>: the subscriber list is being prepared. For large lists, this may take a few minutes. The backend displays this status as &quot;Pending&quot;.</li><li><strong>Active</strong>: emails are being sent. Some subscribers may have already received the message.</li><li><strong>Sent</strong>: all emails have been delivered. The campaign dashboard shows open rates and unsubscribe counts.</li><li><strong>Cancelled</strong>: the campaign was stopped before completion.</li><li><strong>Archived</strong>: the campaign has been archived and its subscriber tracking data deleted.</li></ul><h2 id="scheduling-and-automation"><a href="#scheduling-and-automation" class="header-anchor">#</a> Scheduling and Automation</h2><p>The plugin processes campaigns automatically using the system scheduler. Pending campaigns are checked and active campaigns are sent in batches every 5 minutes.</p><p>If your scheduler is not running, you can manually process campaigns with:</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan campaign:run
</code></pre></div>`,28)),e[2]||(e[2]=t("p",null,[a("Make sure your "),t("a",{href:"https://docs.octobercms.com/3.x/setup/scheduler.html",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("cron table is configured"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),t("span",{class:"sr-only"},"(opens new window)")])]),a(" for automated campaign processing in production.")],-1)),e[3]||(e[3]=s('<h2 id="try-it-out"><a href="#try-it-out" class="header-anchor">#</a> Try It Out</h2><ol><li>Create a new campaign and fill in the content fields</li><li>Send a test message to your own email address</li><li>Launch the campaign to your &quot;Newsletter&quot; list</li><li>Check the campaign status as it progresses from Pending to Sent</li><li>Open the test email and verify the &quot;View in browser&quot; and &quot;Unsubscribe&quot; links work</li></ol><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Continue to <a href="./customizing-the-template.html">Customizing the Template</a> to replace the default template with your own branding and layout.</p>',4))])}const w=l(g,[["render",h]]);export{v as __pageData,w as default};
